import{_ as s,o as a,c as o,a3 as t}from"./chunks/framework.goqT_hzs.js";const k=JSON.parse('{"title":"USB protocol","description":"","frontmatter":{},"headers":[],"relativePath":"developers/protocol.md","filePath":"developers/protocol.md"}'),i={name:"developers/protocol.md"};function n(r,e,c,d,l,h){return a(),o("div",null,[...e[0]||(e[0]=[t(`<h1 id="usb-protocol" tabindex="-1">USB protocol <a class="header-anchor" href="#usb-protocol" aria-label="Permalink to &quot;USB protocol&quot;">​</a></h1><p>s32 is the supported client for the S32 Editor USB interface. This page is the overview for anyone writing their own.</p><h2 id="interface" tabindex="-1">Interface <a class="header-anchor" href="#interface" aria-label="Permalink to &quot;Interface&quot;">​</a></h2><p>A vendor USB interface: VID <code>0483</code>, PID <code>A56E</code>, bulk endpoints <code>0x05</code> (out) and <code>0x85</code> (in). One client at a time, with no password (<a href="./connecting#usb">Connect</a>).</p><p>The protocol version is <strong>3</strong>. <code>hello</code> reports it, and a client that speaks another version is refused instead of misread. The s32 version (<code>s32 --version</code>) is separate from the firmware version.</p><h2 id="session" tabindex="-1">Session <a class="header-anchor" href="#session" aria-label="Permalink to &quot;Session&quot;">​</a></h2><ol><li>Claim the interface.</li><li>Send <code>hello</code>. Check that <code>protocolVersion</code> is 3.</li><li>Send commands. Each request is a CRC-checked frame. The reply carries a status and an optional payload.</li><li>Subscribe to events for live updates (<code>watch</code> in s32).</li></ol><p>Every reply carries the command and <code>seq</code> of the request it answers. Match both. A client stopped mid-transfer leaves unread replies behind, and the next client gets them first. s32 starts at a random <code>seq</code>, drops anything waiting before <code>hello</code>, and skips replies that don&#39;t match. A new <code>hello</code> ends any push or pull the last client left open.</p><p>Two statuses come from the rules, not from errors: <code>Forbidden</code> (that action is panel-only) and <code>TooMany</code> (changes sent faster than the S32 takes them; wait and retry).</p><h2 id="discovering-the-device" tabindex="-1">Discovering the device <a class="header-anchor" href="#discovering-the-device" aria-label="Permalink to &quot;Discovering the device&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">s32</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --usb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hello</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">s32</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --usb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> schema</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --emit-schema-json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> schema.json</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">s32</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> layout</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --emit-layout-json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> layout.json</span></span></code></pre></div><p><code>schema</code> lists device types, parameter names and enum tables (macro modes, menus). <code>layout</code> describes the <code>.s32p</code> project file for tools that decode it. It needs no S32.</p><p>Names such as <code>mode=cc</code>, <code>clockMode=internal</code> and <code>view nav racks</code> are s32 words. On the wire they are the integers in the schema&#39;s enum tables.</p>`,13)])])}const m=s(i,[["render",n]]);export{k as __pageData,m as default};
